export default function PayslipsPage() {
  const [searchParams] = useSearchParams();
  const batchId = searchParams.get("batchId");
  const { user } = useAuth(); const [rows, setRows] = useState([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [notice, setNotice] = useState(""); const [downloadingId, setDownloadingId] = useState("");
  const load = useCallback(async () => { setLoading(true); setError(""); try { if (user.role === "employee") { setRows((await getMyPayslips()).rows); } else if (batchId) { setRows((await getBatchPayslips(batchId)).rows); } else { const batches = await getPaymentBatches({ status: "completed", limit: 100 }); const results = await Promise.all(batches.rows.map((batch) => getBatchPayslips(batch.id))); const unique = new Map(results.flatMap((result) => result.rows).map((payslip) => [payslip.id, payslip])); setRows([...unique.values()].sort((a, b) => new Date(b.generatedAt) - new Date(a.generatedAt))); } } catch (requestError) { setError(getErrorMessage(requestError, "Unable to load payslips.")); } finally { setLoading(false); } }, [user.role, batchId]);
  useEffect(() => { load(); }, [load]);
  const download = async (payslip) => { setDownloadingId(payslip.id); try { const response = await downloadPayslipPdf(payslip.id); setNotice(`${saveBlobResponse(response, `${payslip.payslipReference}.pdf`)} downloaded.`); } catch (requestError) { setError(getErrorMessage(requestError, "Payslip PDF download failed.")); } finally { setDownloadingId(""); } };
  return <Box className="page-enter content-page"><PageHeader title={user.role === "employee" ? "My payslips" : "Employee payslips"} subtitle={user.role === "employee" ? "View and download your approved payroll statements." : batchId ? "Payslips for the selected payment batch." : "Review payslips created by completed payment batches."} />
