        expect(retained.status).toBe("hrms_sync_failed");
        expect(await PaymentBatchItem.count({ where: { payment_batch_id: batchId } })).toBe(1);
        expect(await Payslip.count({ where: { payment_batch_id: batchId } })).toBe(0);
